CREATE TABLE IF NOT EXISTS hr_person_position_history (id CHAR(36) PRIMARY KEY, person_id CHAR(36) NOT NULL, sequence SMALLINT NOT NULL, effective_on DATE NOT NULL, description VARCHAR(500) NOT NULL, position_number VARCHAR(32) NULL, position_type VARCHAR(120) NULL, level VARCHAR(120) NULL, salary DECIMAL(10,2) NULL, position_allowance DECIMAL(10,2) NULL, reference VARCHAR(255) NULL, created_at DATETIME NOT NULL, CONSTRAINT hr_person_position_history_person_fk FOREIGN KEY (person_id) REFERENCES person(id), UNIQUE KEY hr_person_position_history_order (person_id, sequence));
